CREATE OR REPLACE FUNCTION mschool.payroll_schedule_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$declare d date; st text;begin
for d in select distinct date_trunc('month',x)::date from unnest(array[case when tg_op<>'INSERT' then old.date end,case when tg_op<>'DELETE' then new.date end])x where x is not null loop
 perform pg_advisory_xact_lock(hashtextextended('payroll:'||d,57031));select stage into st from mschool.payroll_months where month=d for update;
 if st in ('wife','pastor','approved') then raise exception 'payroll_month_locked_return_first' using errcode='40001';end if;
 update mschool.payroll_months set revision=revision+1,saved=false,updated_at=now() where month=d;
end loop;return case when tg_op='DELETE' then old else new end;end$function$

CREATE OR REPLACE FUNCTION public.school_payroll_action(p_actor text, p_action text, p_month date, p_revision bigint DEFAULT NULL::bigint, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare a jsonb;aid text;b mschool.payroll_months;target text;comment text;roster jsonb;rates jsonb;photos jsonb;history jsonb;snap jsonb;begin
a:=mschool.payroll_actor(p_actor);aid:=a->>'id';if p_month is null or extract(day from p_month)<>1 then raise exception 'invalid_month';end if;
perform pg_advisory_xact_lock(57203,2);perform pg_advisory_xact_lock(hashtextextended('payroll:'||p_month,57031));select * into b from mschool.payroll_months where month=p_month for update;
if p_action='rates_save' then
 if aid not in ('2026M0001','2026M0002') then raise exception 'wage_owner_required' using errcode='42501';end if;
 if not exists(select 1 from mschool.users where id=p_payload->>'worker_id' and role_type in ('老師','工讀生')) then raise exception 'teacher_or_worker_required';end if;
 if (p_payload->>'effective_from')::date is null or (p_payload->>'hourly_wage')::numeric is null then raise exception 'rate_required';end if;
 if exists(select 1 from mschool.payroll_months where stage in ('wife','pastor','approved') and (p_payload->>'effective_from')::date<month+interval '1 month') then raise exception 'rate_affects_locked_month_return_first';end if;
 insert into mschool.payroll_rates(worker_id,effective_from,hourly_wage,updated_by)values(p_payload->>'worker_id',(p_payload->>'effective_from')::date,(p_payload->>'hourly_wage')::numeric,aid)on conflict(worker_id,effective_from)do update set hourly_wage=excluded.hourly_wage,updated_by=aid,updated_at=now();
 insert into mschool.payroll_audit(actor_id,action,payload)values(aid,'rate_saved',p_payload);update mschool.schedules s set hourly_wage=(select hourly_wage from mschool.payroll_rates r where r.worker_id=s.worker_id and r.effective_from<=s.date order by effective_from desc limit 1)where s.worker_id=p_payload->>'worker_id' and s.date>=(p_payload->>'effective_from')::date and not exists(select 1 from mschool.payroll_months m where m.stage in('wife','pastor','approved')and s.date>=m.month and s.date<m.month+interval '1 month');
 update mschool.payroll_months set saved=false,revision=revision+1,updated_at=now() where stage in ('yuting','enru') and month+interval '1 month'>(p_payload->>'effective_from')::date;
 return jsonb_build_object('ok',true);
end if;
if p_action='get' then
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'role_type',role_type,'status',status)order by id),'[]') into roster from mschool.users where role_type in ('老師','工讀生');
 select coalesce(jsonb_agg(to_jsonb(r)order by worker_id,effective_from),'[]') into rates from mschool.payroll_rates r;
 select coalesce(jsonb_agg(to_jsonb(p)order by created_at),'[]') into photos from mschool.payroll_photos p where month_id=b.id;
 select coalesce(jsonb_agg(to_jsonb(h)order by id),'[]') into history from mschool.payroll_audit h where month_id=b.id;
 snap:=case when b.stage in ('wife','pastor','approved')then b.snapshot else mschool.payroll_snapshot(p_month)end;
 return jsonb_build_object('ok',true,'actor_id',aid,'can_set_rates',aid in ('2026M0001','2026M0002'),'can_edit',b.stage in ('yuting','enru') and aid=mschool.payroll_stage_actor(b.stage),'can_review',aid=mschool.payroll_stage_actor(b.stage),'batch',case when b.id is null then null else to_jsonb(b)end,'snapshot',snap,'roster',roster,'rates',rates,'photos',photos,'history',history);
end if;
if b.id is null then raise exception 'month_not_settled_yet';end if;
if b.revision is distinct from p_revision then raise exception 'payroll_changed_reload' using errcode='40001';end if;
if aid is distinct from mschool.payroll_stage_actor(b.stage) then raise exception 'wrong_review_stage' using errcode='42501';end if;
if p_action='save' then
 if b.stage not in ('yuting','enru') then raise exception 'stage_read_only';end if;
 update mschool.payroll_months set saved=true,snapshot=mschool.payroll_snapshot(p_month),revision=revision+1,updated_at=now() where id=b.id returning * into b;
 insert into mschool.payroll_audit(month_id,actor_id,action,from_stage,to_stage,payload)values(b.id,aid,'saved',b.stage,b.stage,b.snapshot);
 return jsonb_build_object('ok',true,'revision',b.revision);
end if;
comment:=btrim(coalesce(p_payload->>'comment',''));
if p_action='return' then
 if b.stage not in ('enru','wife','pastor') or length(comment)<1 or length(comment)>2000 then raise exception 'return_reason_required';end if;
 target:=case b.stage when 'enru' then 'yuting' when 'wife' then 'enru' when 'pastor' then 'wife'end;
else
 if p_action<>'submit' then raise exception 'invalid_payroll_action';end if;
 if b.stage in ('yuting','enru') then
  if not b.saved then raise exception 'save_before_submit';end if;
  snap:=mschool.payroll_snapshot(p_month);
  if snap->>'source_hash' is distinct from b.snapshot->>'source_hash' then raise exception 'payroll_changed_save_again' using errcode='40001';end if;
  if (snap->>'missing_rates')::int>0 then raise exception 'hourly_rates_missing';end if;
  if not exists(select 1 from mschool.payroll_photos where month_id=b.id)then raise exception 'attendance_photo_required';end if;
 end if;
 target:=case b.stage when 'yuting' then 'enru' when 'enru' then 'wife' when 'wife' then 'pastor' when 'pastor' then 'approved'end;
 if target is null then raise exception 'invalid_payroll_stage';end if;
end if;
insert into mschool.payroll_audit(month_id,actor_id,action,from_stage,to_stage,comment,payload)values(b.id,aid,p_action,b.stage,target,comment,b.snapshot);
update mschool.payroll_months set stage=target,saved=false,revision=revision+1,updated_at=now() where id=b.id returning * into b;
if target<>'approved' then perform mschool.payroll_queue(b);end if;
return jsonb_build_object('ok',true,'stage',target,'revision',b.revision);
end$function$

CREATE OR REPLACE FUNCTION public.school_payroll_photo(p_actor text, p_month date, p_revision bigint, p_photo uuid DEFAULT NULL::uuid, p_file text DEFAULT NULL::text, p_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$declare a jsonb;b mschool.payroll_months;begin a:=mschool.payroll_actor(p_actor);perform pg_advisory_xact_lock(57203,2);perform pg_advisory_xact_lock(hashtextextended('payroll:'||p_month,57031));select * into b from mschool.payroll_months where month=p_month for update;if b.id is null or b.stage not in ('yuting','enru') or a->>'id' is distinct from mschool.payroll_stage_actor(b.stage)then raise exception 'photo_stage_forbidden' using errcode='42501';end if;
if p_photo is not null and exists(select 1 from mschool.payroll_photos where id=p_photo and month_id=b.id and uploaded_by=a->>'id')then return jsonb_build_object('ok',true,'duplicate',true);end if;
if b.revision is distinct from p_revision then raise exception 'payroll_changed_reload' using errcode='40001';end if;
if p_file is not null then
 if p_photo is null or p_file !~ '^[A-Za-z0-9_-]{10,120}$' or length(p_name)not between 1 and 180 then raise exception 'invalid_photo';end if;
 insert into mschool.payroll_photos(id,month_id,drive_file_id,file_name,uploaded_by,uploaded_stage)values(p_photo,b.id,p_file,p_name,a->>'id',b.stage);
 update mschool.payroll_months set revision=revision+1,saved=false,updated_at=now()where id=b.id;
 insert into mschool.payroll_audit(month_id,actor_id,action,from_stage,to_stage,payload)values(b.id,a->>'id','photo_uploaded',b.stage,b.stage,jsonb_build_object('photo_id',p_photo,'file_name',p_name));
end if;
return jsonb_build_object('ok',true,'batch',to_jsonb(b));end$function$

CREATE OR REPLACE FUNCTION public.school_payroll_schedule(p_actor text, p_month date, p_revision bigint, p_method text, p_id bigint, p_rows jsonb, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$declare a jsonb;b mschool.payroll_months;item jsonb;r jsonb;begin
a:=mschool.payroll_actor(p_actor);perform pg_advisory_xact_lock(57203,2);perform pg_advisory_xact_lock(hashtextextended('payroll:'||p_month,57031));select * into b from mschool.payroll_months where month=p_month for update;
if b.id is null or b.stage not in ('yuting','enru')or a->>'id' is distinct from mschool.payroll_stage_actor(b.stage)then raise exception 'wrong_review_stage' using errcode='42501';end if;
if b.revision is distinct from p_revision then raise exception 'payroll_changed_reload' using errcode='40001';end if;
if p_method not in ('POST','PATCH','DELETE')then raise exception 'invalid_schedule_operation';end if;
if p_method in ('PATCH','DELETE')and not exists(select 1 from mschool.schedules where id=p_id and date>=p_month and date<p_month+interval '1 month')then raise exception 'schedule_outside_review_month';end if;
for item in select value from jsonb_array_elements(p_rows)loop if (item->>'date')::date<p_month or (item->>'date')::date>=p_month+interval '1 month' then raise exception 'schedule_outside_review_month';end if;end loop;
r:=public.school_mutate_schedules(p_actor,p_method,p_id,p_rows,p_request,false);return r;end$function$
